class DataModel(db.Model):
    __tablename__ = "data_model"
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64))
    filename = db.Column(db.Text)

    def __repr__(self):
        return '<DataModel %r>' % (self.name)
